changeSet.sql:
DO $$
DECLARE
    message_templates TEXT[] := ARRAY[
        'Hey! How are you?','Thanks for following!','Love your recent post!',
        'Let''s catch up soon','That photo is amazing!','What camera do you use?',
        'Where is this place?','Great content!','Haha that''s so funny',
        'Can''t wait to see more','This is goals','Stunning!','You inspire me',
        'Following back!','Nice to meet you','Do you have any tips?',
        'This made my day','Beautiful shot!','Keep up the great work','Wow just wow'];

    profile_ids  BIGINT[];
    p1           BIGINT;
    p2           BIGINT;
    chat_id      UUID;
    sender_id    BIGINT;
    num_messages INTEGER;
    i            INTEGER;
    j            INTEGER;
    k            INTEGER;
BEGIN
    PERFORM setseed(0.51);
    profile_ids := ARRAY(SELECT id FROM profiles ORDER BY id);

    FOR i IN 1..array_length(profile_ids, 1) LOOP
        FOR j IN i + 1..array_length(profile_ids, 1) LOOP
            CONTINUE WHEN random() > 0.20;

            p1 := profile_ids[i];
            p2 := profile_ids[j];

            INSERT INTO chats DEFAULT VALUES RETURNING id INTO chat_id;
            INSERT INTO chat_participants (chat_id, profile_id) VALUES (chat_id, p1);
            INSERT INTO chat_participants (chat_id, profile_id) VALUES (chat_id, p2);

            num_messages := 3 + (floor(random() * 8))::int;

            FOR k IN 1..num_messages LOOP
                sender_id := CASE WHEN random() < 0.5 THEN p1 ELSE p2 END;
                INSERT INTO messages (chat_id, sender_profile_id, text)
                VALUES (chat_id, sender_id,
                        message_templates[1 + (floor(random() * array_length(message_templates, 1)))::int]);
            END LOOP;

            UPDATE chats SET last_message_at = NOW() WHERE id = chat_id;
        END LOOP;
    END LOOP;
END $$;

changeSet.rollback:
DELETE FROM messages;
DELETE FROM chat_participants;
DELETE FROM chats;
